import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import gameService from "../../services/gameService";
import WheelGamePreview from '../../img/WheelGamePreview.jpg';

function GamesPreview() {
    // Состояние для данных
    const [games, setGames] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    
    // Если нужно использовать данные пользователя
    const { currentUser } = useAuth();
    
    // Функция загрузки данных
    const loadGames = async () => {
        try {
            setLoading(true);
            setError(null);
            
            const data = await gameService.getUserGames();
            setGames(data.games || []);
            
        } catch (err) {
            setError('Не удалось загрузить игры');
            console.error('Ошибка загрузки:', err);
        } finally {
            setLoading(false);
        }
    };
    
    // Загружаем данные при монтировании
    useEffect(() => {
        loadGames();
    }, []);
    
    // Кнопка обновления
    const refreshGames = () => {
        loadGames();
    };
    
    // Иконки для разных типов игр
    const getGameIcon = (gameType) => {
        switch (gameType) {
            case 'wheel': return '🎡';
            case 'quiz': return '❓';
            case 'match': return '🔗';
            default: return '🎮';
        }
    };
    
    // Цвета для разных типов игр
    const getGameColor = (gameType) => {
        switch (gameType) {
            case 'wheel': return 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)';
            case 'quiz': return 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)';
            case 'match': return 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)';
            default: return 'linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)';
        }
    };
    
    // Обработка состояний
    if (loading) {
        return (
            <div className="games-preview-loading">
                <div className="loading-spinner">🎮</div>
                <h2>Загружаем ваши игры...</h2>
            </div>
        );
    }
    
    if (error) {
        return (
            <div className="games-preview-error">
                <div className="error-icon">⚠️</div>
                <h2>Упс! Что-то пошло не так</h2>
                <p>{error}</p>
                <button onClick={refreshGames} className="retry-button">
                    🔄 Попробовать снова
                </button>
            </div>
        );
    }
    
    if (games.length === 0) {
        return (
            <div className="games-preview-empty">
                <div className="empty-icon">🎯</div>
                <h2>Пока пусто!</h2>
                <p>Создайте свою первую игру и она появится здесь</p>
                <button onClick={refreshGames} className="refresh-button">
                    🔄 Обновить
                </button>
            </div>
        );
    }
    
    // Отображение списка игр
    return (
        <div className="games-preview">
            <div className="games-header">
                <h1>🎮 Мои игры</h1>
                <p className="games-subtitle">Выберите игру для начала или создайте новую!</p>
                <button onClick={refreshGames} className="refresh-all-button">
                    🔄 Обновить все
                </button>
            </div>
            
            <div className="games-grid">
                {games.map(game => (
                    <div key={game.id} className="game-card" style={{
                        background: getGameColor(game.game_type)
                    }}>
                        <div className="game-card-header">
                            <span className="game-icon">{getGameIcon(game.game_type)}</span>
                            <span className="game-type-badge">{game.game_type}</span>
                        </div>
                        
                        <div className="game-preview-image">
                            <img 
                                src={WheelGamePreview} 
                                alt={`${game.game_name} preview`}
                                onError={(e) => {
                                    e.target.style.display = 'none';
                                }}
                            />
                            <div className="game-preview-overlay">
                                <span className="preview-icon">👁️</span>
                            </div>
                        </div>
                        
                        <div className="game-card-content">
                            <h3 className="game-title">{game.game_name}</h3>
                            <div className="game-meta">
                                <span className="game-date">📅 {new Date(game.created_at).toLocaleDateString('ru-RU')}</span>
                            </div>
                        </div>
                        
                        <div className="game-card-actions">
                            <button 
                                className="play-button"
                                onClick={() => console.log('Играть:', game.id)}
                            >
                                ▶️ Играть
                            </button>
                            <button 
                                className="edit-button"
                                onClick={() => console.log('Редактировать:', game.id)}
                            >
                                ✏️ Изменить
                            </button>
                            <button 
                                className="delete-button"
                                onClick={() => {
                                    if (window.confirm('Удалить эту игру?')) {
                                        console.log('Удалить:', game.id);
                                    }
                                }}
                            >
                                🗑️
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default GamesPreview;
